package com.lyrashop.user.controller;import java.util.Locale;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import com.lyrashop.user.entity.NewsletterSubscription;import com.lyrashop.user.repository.NewsletterRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.*;
@RestController @RequestMapping("/api/v1/newsletter/subscriptions") public class NewsletterController{private final NewsletterRepository r;public NewsletterController(NewsletterRepository r){this.r=r;}public record Request(@NotBlank @Email String email){}
 @PostMapping @Transactional public ResponseEntity<Void> subscribe(@Valid @RequestBody Request q){String e=q.email().strip().toLowerCase(Locale.ROOT);var s=r.findByEmail(e).orElseGet(()->new NewsletterSubscription(e));s.activate();r.save(s);return ResponseEntity.status(201).build();}
 @DeleteMapping @Transactional public ResponseEntity<Void> unsubscribe(@Valid @RequestBody Request q){r.findByEmail(q.email().strip().toLowerCase(Locale.ROOT)).ifPresent(s->{s.deactivate();r.save(s);});return ResponseEntity.noContent().build();}}
